insert into lektionskollen.plans(id,school_id,request_id,title,subject,year_group,minutes,language,body,approved,created_at) values
 ('20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-0000000000a1','10000000-0000-0000-0000-000000000001','P1','Matematik','7',60,'sv','{"exit": {"a": "1/2. En halv är 4/8, och 4/8 är mer än 3/8.", "q": "Vilket är störst — 3/8 eller 1/2?"}, "goal": "Jag kan placera bråk på tallinjen.", "ahead": "Be dem skriva en egen uppgift av samma typ, med facit, till en kompis.", "board": "Dagens mål\nJag kan placera bråk på tallinjen.\n\nVar på tallinjen mellan 0 och 1 hamnar 3/4?", "model": {"a": "Vid den tredje av fyra markeringar — tre fjärdedelar av vägen mot 1.", "p": "Var på tallinjen mellan 0 och 1 hamnar 3/4?", "st": [{"b": "0 ——————————— 1", "s": "Rita tallinjen. Noll här, ett här."}, {"b": "nämnare 4 → dela i 4 lika delar", "s": "Titta på nämnaren, talet under strecket. Fyra betyder att sträckan delas i fyra lika delar."}, {"b": "0 — 1/4 — 2/4 — 3/4 — 1", "s": "Sätt ut markeringarna. En fjärdedel, två fjärdedelar, tre fjärdedelar."}, {"b": "3/4 = tredje markeringen", "s": "Täljaren, talet över strecket, säger hur många steg vi går. Tre steg. Där är tre fjärdedelar."}], "ta": "Dela sträckan i fem delar och gå två steg. Strax före mitten.", "tq": "Var hamnar 2/5?"}, "stuck": "Gå tillbaka till exemplet på tavlan och gör uppgift 1 med dem, steg för steg.", "tasks": [{"a": "Precis i mitten.", "q": "Placera 1/2 på en tallinje mellan 0 och 1.", "tier": "core"}, {"a": "2/3. Med samma nämnare: 10/15 mot 9/15.", "q": "Vilket är störst, 2/3 eller 3/5?", "tier": "core"}, {"a": "En fjärdedel förbi 1. Täljaren är större än nämnaren, så talet är större än ett.", "q": "Placera 5/4 på en tallinje mellan 0 och 2.", "tier": "core"}, {"a": "1/2. Delas helheten i två delar blir varje del större än om den delas i fyra.", "q": "Vilket är störst, 1/2 eller 1/4?", "tier": "support"}, {"a": "Fyra. 4/8 = 1/2.", "q": "Hur många åttondelar är lika mycket som en halv?", "tier": "support"}, {"a": "En sjättedel förbi 1. Täljaren är större än nämnaren, så talet är större än ett.", "q": "Placera 7/6 på en tallinje mellan 0 och 2 och förklara hur du vet var den hamnar.", "tier": "extension"}, {"a": "Till exempel 3/5, 2/3 och 3/4. Godkänt om alla tre är större än 1/2 och mindre än 1.", "q": "Skriv tre bråk som ligger mellan 1/2 och 1.", "tier": "extension"}], "title": "Bråk på tallinjen", "wrong": "Blir det stökigt: tyst skrivande i fem minuter, samla in, avsluta med exit-frågan.", "phases": [{"n": "Repetition", "t": "00:00–00:08", "say": "\"Innan vi börjar — två frågor om sådant ni redan kan. Inga händer upp, jag frågar.\"", "board": "Att dela en helhet i lika delar.", "checks": [{"a": "Fyra.", "q": "Hur många fjärdedelar går på en hel?"}, {"a": "En halv. Ju fler delar helheten delas i, desto mindre blir varje del.", "q": "Vilket är störst, en halv eller en tredjedel?"}], "expect": "Alla kommer inte ihåg. Det är meningen — därför repeterar vi.", "pupils": "Svarar när du pekar på dem. Skriv svaren på tavlan."}, {"n": "Genomgång på tavlan", "t": "00:08–00:20", "say": "\"Titta på tavlan. Jag går igenom ett exempel och säger varje steg högt. Skriv av.\"", "board": "0 ——————————— 1\nnämnare 4 → dela i 4 lika delar\n0 — 1/4 — 2/4 — 3/4 — 1\n3/4 = tredje markeringen", "checks": [{"a": "Vid den tredje av fyra markeringar — tre fjärdedelar av vägen mot 1.", "q": "Var på tallinjen mellan 0 och 1 hamnar 3/4?"}], "expect": "Tyst i klassrummet här. Om det blir prat, stanna och vänta.", "pupils": "Tittar och skriver av exemplet steg för steg."}, {"n": "Vi gör ett tillsammans", "t": "00:20–00:30", "say": "\"Nu gör vi ett tillsammans. Jag skriver, ni säger vad jag ska göra.\"", "board": "Var hamnar 2/5?", "checks": [{"a": "Dela sträckan i fem delar och gå två steg. Strax före mitten.", "q": "Var hamnar 2/5?"}], "expect": "Två eller tre räcker upp handen. Fråga någon som inte gjorde det.", "pupils": "Säger nästa steg högt. En elev får komma fram och skriva."}, {"n": "Eget arbete", "t": "00:30–00:52", "say": "\"Nu arbetar ni själva. Jag går runt. Räck upp handen om ni fastnar.\"", "board": "1. Placera 1/2 på en tallinje mellan 0 och 1.\n2. Vilket är störst, 2/3 eller 3/5?\n3. Placera 5/4 på en tallinje mellan 0 och 2.", "checks": [], "expect": "De snabbaste är klara efter halva tiden — se \"klara tidigt\".", "pupils": "Arbetar med uppgifterna i boken eller på arbetsbladet."}, {"n": "Exit-fråga", "t": "00:52–00:60", "say": "\"Sista fem minuterna. Skriv svaret på en lapp med ert namn och lämna den till mig på vägen ut.\"", "board": "Vilket är störst — 3/8 eller 1/2?", "checks": [{"a": "1/2. En halv är 4/8, och 4/8 är mer än 3/8.", "q": "Vilket är störst — 3/8 eller 1/2?"}], "expect": "Räkna lapparna mot närvaron. Saknas någon, fråga vem.", "pupils": "Skriver svaret på en lapp och lämnar in den."}], "recall": {"qs": [{"a": "Fyra.", "q": "Hur många fjärdedelar går på en hel?"}, {"a": "En halv. Ju fler delar helheten delas i, desto mindre blir varje del.", "q": "Vilket är störst, en halv eller en tredjedel?"}], "why": "Att dela en helhet i lika delar."}, "first90": ["Stå vid dörren. Säg god morgon till varje elev som kommer in.", "Skriv ditt namn på tavlan innan lektionen börjar.", "Säg: \"Jag heter [ditt namn] och jag är här idag. Vi arbetar med matematik. Sitt där ni brukar sitta.\"", "Ta närvaron högt från listan. Det tar 60 sekunder och sätter tonen."], "summary": "Eleverna repeterar det de behöver, ser ett exempel på tavlan, gör ett tillsammans med dig och arbetar sedan själva. Du behöver inga förkunskaper — varje steg står utskrivet och alla svar finns med.", "handover": "Vi hann bråk på tallinjen.", "readTime": "3 min", "equipment": {"need": "Whiteboard och penna. Inget annat krävs.", "where": "Linjaler i lådan under tavlan. Arbetsbladet i facket märkt Åk 7.", "fallback": "Om projektorn är trasig spelar det ingen roll — hela lektionen går på tavlan."}, "materials": [{"h": "Exempel", "body": "Var på tallinjen mellan 0 och 1 hamnar 3/4?\n\n0 ——————————— 1\nnämnare 4 → dela i 4 lika delar\n0 — 1/4 — 2/4 — 3/4 — 1\n3/4 = tredje markeringen"}, {"h": "Arbetsblad", "body": "1. Placera 1/2 på en tallinje mellan 0 och 1.\n2. Vilket är störst, 2/3 eller 3/5?\n3. Placera 5/4 på en tallinje mellan 0 och 2.\n\n(Skriv uppgifterna på tavlan om kopiatorn inte fungerar.)"}], "curriculum": "Matematik Åk 7 — centralt innehåll.", "misconceptions": [{"s": "Dela en pizza i fyra bitar, och en annan i åtta. Vilken bit vill du ha? Fler delar betyder mindre delar.", "t": "1/8 är större än 1/4 eftersom 8 är större än 4.", "w": "De jämför nämnarna som vanliga tal och glömmer att nämnaren säger hur många bitar helheten delats i."}]}'::jsonb,false, now()-interval '2 hour'),
