rkeringen"}, {"h": "Arbetsblad", "body": "1. Placera 1/2 på en tallinje mellan 0 och 1.\n2. Vilket är störst, 2/3 eller 3/5?\n3. Placera 5/4 på en tallinje mellan 0 och 2.\n\n(Skriv uppgifterna på tavlan om kopiatorn inte fungerar.)"}], "curriculum": "Matematik Åk 7 — centralt innehåll.", "misconceptions": [{"s": "Dela en pizza i fyra bitar, och en annan i åtta. Vilken bit vill du ha? Fler delar betyder mindre delar.", "t": "1/8 är större än 1/4 eftersom 8 är större än 4.", "w": "De jämför nämnarna som vanliga tal och glömmer att nämnaren säger hur många bitar helheten delats i."}]}'::jsonb,false, now());
insert into lektionskollen.school_settings (school_id, assist_cap) values ('00000000-0000-0000-0000-0000000000a1', 2);

grant usage on schema public to anon, authenticated;

-- A first approval shares the plan (the bug 20261028d fixed).
select public.lk_approve_as('20000000-0000-0000-0000-000000000001', 'coordinator', 'Matematik', 'Anna');
do $$ begin
  if not (select shared from lektionskollen.plans where title = 'P1') then raise exception 'approval did not share'; end if;
end $$;

-- The share token is read here: anon cannot see the tables, only the functions.
select set_config('smoke.tok', share_token, false) from lektionskollen.plans where title = 'P1';
set role anon;
do $$ declare n int; c jsonb; a jsonb; tok text := current_setting('smoke.tok');
begin
  -- The pool: own plans, plus the other school's shared ones (none yet).
  n := jsonb_array_length(public.lk_pool(null, null, 'all', 'any', 'any'));
  if n <> 2 then raise exception 'pool has % rows, expected 2', n; end if;
  -- The cover table: one object, generated plans included.
  c := public.lk_cover_plans();
  if c -> 'ABS1' ->> 'title' is distinct from 'P1' then raise exception 'cover plans: %', c; end if;
  -- Extra help is metered (the demo school's cap is 2).
  perform public.lk_assist_take(tok); perform public.lk_assist_take(tok);
  a := public.lk_assist_take(tok);
  if (a ->> 'ok')::boolean then raise exception 'assist cap not enforced: %', a; end if;
  -- Another school's unshared plan is not ours to write to.
  if public.lk_fill_alt('20000000-0000-0000-0000-000000000003', 'en', '{}'::jsonb) then raise exception 'wrote to another school'; end if;
end $$;

-- A lesson planned by mistake can be taken back; one already given cannot.
do $$ declare r jsonb; ok boolean;
begin
  r := public.lk_log_run('20000000-0000-0000-0000-000000000001', '7A', '10:00–11:00', null, null,
                         ((now() at time zone 'Europe/Stockholm')::date + 1));
  ok := public.lk_unlog_run(r ->> 'run_token');
  if not ok then raise exception 'could not take back a planned lesson'; end if;
  if public.lk_unlog_run(r ->> 'run_token') then raise exception 'took back the same lesson twice'; end if;
  r := public.lk_log_run('20000000-0000-0000-0000-000000000001', '7A', null, null, null,
                         ((now() at time zone 'Europe/Stockholm')::date - 3));
  if public.lk_unlog_run(r ->> 'run_token') then raise exception 'took back a lesson in the past'; end if;
  -- Problem reports: the browser can add one, a duplicate error is folded in.
  if not public.lk_report('user', 'The print button does nothing', '/index.html', 'smoke') then raise exception 'report refused'; end if;
  perform public.lk_report('error', 'TypeError: x is undefined', '/index.html', 'smoke');
  perform public.lk_report('error', 'TypeError: x is undefined', '/index.html', 'smoke');
  if public.lk_report('nonsense', 'x') then raise exception 'unknown report kind accepted'; end if;
end $$;

-- What the browser must not be able to call.
do $$ begin
  begin perform public.lk_quota_refund('00000000-0000-0000-0000-0000000000a1'); raise exception 'anon can refund quota';
  exception when insufficient_privilege then null; end;
  begin perform public.lk_plan_standing('20000000-0000-0000-0000-000000000001'); raise exception 'anon can read plan standing';
  exception when insufficient_privilege then null; end;
  begin perform 1 from lektionskollen.problem_reports; raise exception 'anon can read problem reports';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
do $$ begin
  if (select count(*) from lektionskollen.problem_reports) <> 2 then raise exception 'expected 2 reports (one user, one folded error)'; end if;
end $$;
select 'database smoke test passed' as result;
